56:     });
57:     this.unsubscribeFunctions.push(unsubProgress);
58: 
59:     // 监听后端日志
60:     const unsubLog = window.electronAPI.backend.onLog((message, level) => {
61:       this.logCallbacks.forEach((cb) => cb(message, level));
62:     });
63:     this.unsubscribeFunctions.push(unsubLog);
